import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def get_pkgs(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            key = f\"{name} ({fw['framework']})\"
            result[key] = {p['id']: p['resolvedVersion'] for p in fw['topLevelPackages']}
    return result

b = get_pkgs(baseline)
a = get_pkgs(after)

changes = []
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, 'N/A')
        av = ap.get(pkg, 'N/A')
        if bv != av:
            changes.append((proj, pkg, bv, av))

if changes:
    print('VERSION CHANGES:')
    for proj, pkg, bv, av in changes:
        print(f'  {proj}: {pkg} {bv} -> {av}')
else:
    print('No version changes - conversion is version-neutral!')
